/**
 * A fingerprint of what each *published* version recorded.
 *
 * The entry beside this one is a claim about a tarball that exists on a
 * registry and can never change, and the guard that was supposed to hold it
 * still said so in a comment — "a change to an old entry fails here" — while
 * asserting only that the list has no duplicates and more than fifty items.
 * Removing a name from 0.7.0 passed. The comment described a guard nobody had
 * written, which is the most expensive kind of comment.
 *
 * So: sha256 over the entry's items joined by newlines. Editing a published
 * list now means editing this too, which is not something done by accident.
 *
 * Only published versions appear. The working version's surface is *supposed*
 * to move — freezing it would fail on the first honest addition, and a guard
 * that fires on correct work is one somebody deletes.
 */
