  /*
   * The gate release. Thirty-two items 0.7.1 did not have, nothing removed.
   *
   * `Gates` is the one that matters outside this file: `_data/sdk-ledger.ts`
   * keys the marketing site's "may this page show an SDK call" question on the
   * namespace class, so every surface that had been showing `curl` because
   * `gate()` was uninstallable switched over when this version was recorded
   * here — not when it reached npm.
   *
   * Which is the lesson of this entry. npm served 0.8.0 for thirteen hours
   * while this list still ended at 0.7.1, and the site went on refusing a call
   * anybody could already install. Nothing noticed, because no test can reach a
   * registry. `.github/workflows/ci.yml` has a `ledger` job now that can.
   */
