  /*
   * The working version, and nothing is published under it yet.
   *
   * 0.8.0 went to npm, which makes `package.json` at 0.8.0 the exact state the
   * guard below refuses: new code cannot land under a number the registry has
   * already served, because it succeeds everywhere except `npm install`. So
   * the working version steps forward the moment a release lands, and this
   * entry starts as a copy of what shipped.
   *
   * It carries no CHANGELOG.md heading on purpose. There is nothing to say
   * about 0.8.1 yet; the heading arrives with the first change that needs
   * describing, which is also when this list stops matching 0.8.0's. If that
   * first change *adds* to the surface, the number is wrong — additions are a
   * minor, and `version.test.ts` says so rather than leaving it to whoever
   * remembers.
   */
