  /*
   * The Mastra adapter (`generateWithDeliverdApprovals`, `resolveMastraApproval`,
   * `pendingMastraApproval` and the two shapes they read), and the Muse Spark
   * adapter (`runMuseFunctionCalls`, `runMuseToolCalls` and their shapes).
   * Additions only over
   * the published 0.25.1, so a minor: opened as 0.25.2 when 0.25.1 shipped,
   * renamed when the surface grew. Then `deliverd.screen()`, and the rest of
   * Compliance Mode: `deliverd.governance` (AI systems, incidents, authority,
   * frameworks, the ICT register, the summary) and five governance calls on
   * tasks (`govern`, `updateGovernanceProfile`, `requestControlApproval`,
   * `triggerReassessment`, `evidencePack`).
   */
